1463: # process start? Windows reports a process's start time exactly. .NET on Linux derives
1464: # Process.StartTime from a boot time that every process computes for itself
1465: # (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
1466: # values a few milliseconds apart. Outside Windows, less than one second apart counts
1467: # as the same start (a pid is not handed out again that fast).
1468: function Test-SameStartTime {
1469:     param([string]$A, [string]$B)
1470:     if ($A -eq $B) { return $true }
1471:     if ($script:OnWindows) { return $false }
