1473:     $tb = [DateTimeOffset]::MinValue
1474:     $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
1475:     if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
1476:     if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
