1691: # Is a process recorded in a pending record still that process? Returns { Alive; How }.
1692: #   with a recorded start time: alive only when the pid runs with that start time (and
1693: #     that name, when one is recorded) - a different start time means the pid was
1694: #     reused by an unrelated process;
1695: #   without one (older records), or when the live start time cannot be read: alive
1696: #     only when the process looks like codex (Get-CodexRule) - never by pid alone.
1697: function Test-RecordedProcess {
1698:     param([int]$ProcessId, [string]$StartTime = '', [string]$Name = '', [string]$Launcher = '')
1699:     $info = Get-ProcessInfo -ProcessId $ProcessId
1700:     if (-not $info) { return [pscustomobject]@{ Alive = $false; How = 'gone' } }
1701:     if ($StartTime -and $info.start) {
1702:         if (-not (Test-SameStartTime -A $info.start -B $StartTime)) { return [pscustomobject]@{ Alive = $false; How = 'pid reused (start time differs)' } }
1703:         if ($Name -and -not $info.name.Equals($Name, [StringComparison]::OrdinalIgnoreCase)) { return [pscustomobject]@{ Alive = $false; How = "pid reused (now $($info.name))" } }
1704:         return [pscustomobject]@{ Alive = $true; How = 'pid + start time' }
1705:     }
1706:     $rule = Get-CodexRule -Name $info.name -Cmd $info.cmd -Launcher $Launcher
1707:     if ($rule) { return [pscustomobject]@{ Alive = $true; How = "no start time recorded; $rule" } }
1708:     return [pscustomobject]@{ Alive = $false; How = "no start time recorded; pid $ProcessId runs $($info.name), not codex" }
1709: }
